patch:
diff --git a/sample-app/src/routes/tasks.ts b/sample-app/src/routes/tasks.ts
index 58b0c250..8d67993d 100644
--- a/sample-app/src/routes/tasks.ts
+++ b/sample-app/src/routes/tasks.ts
@@ -42,7 +42,10 @@ router.post('/tasks', (req: Request, res: Response) => {
     return;
   }

-  if (body.tags !== undefined && !Array.isArray(body.tags)) {
+  if (
+    body.tags !== undefined &&
+    (!Array.isArray(body.tags) || !body.tags.every((t: unknown) => typeof t === 'string'))
+  ) {
     res.status(400).json({ error: 'tags must be an array of strings' });
     return;
   }
@@ -99,7 +102,10 @@ router.put('/tasks/:id', (req: Request, res: Response) => {
     return;
   }

-  if (body.tags !== undefined && !Array.isArray(body.tags)) {
+  if (
+    body.tags !== undefined &&
+    (!Array.isArray(body.tags) || !body.tags.every((t: unknown) => typeof t === 'string'))
+  ) {
     res.status(400).json({ error: 'tags must be an array of strings' });
     return;
   }
